    [16216] = { enName = "Formula: Enchant Cloak - Greater Resistance", itName = "Formula: Incanta Mantello - Resistenza Superiore", enDescription = "Teaches you how to permanently enchant a cloak so it adds 5 to all resistances.", description = "Insegna a incantare permanentemente un mantello per aumentare di 5 tutte le resistenze." },
    [16223] = { enName = "Formula: Enchant Weapon - Icy Chill", itName = "Formula: Incanta Arma - Toccogelido", enDescription = "Teaches you how to permanently enchant a weapon to give it an icy chill that sometimes slows its target.", description = "Insegna a incantare permanentemente un’arma con un’aura gelida che a volte rallenta il bersaglio." },
