    [16249] = { enName = "Formula: Enchant 2H Weapon - Major Intellect", itName = "Formula: Incanta Arma a Due Mani - Intelletto Maggiore", enDescription = "Teaches you how to permanently enchant a two-handed weapon so it grants +9 Intellect.", description = "Insegna a incantare permanentemente un’arma a due mani per aumentare di 9 l’Intelletto." },
