    [16253] = { enName = "Formula: Enchant Chest - Greater Stats", itName = "Formula: Incanta Torso - Statistiche Superiori", enDescription = "Teaches you how to permanently enchant a piece of chest armor to give +4 to each of the five attributes.", description = "Insegna a incantare permanentemente un’armatura per il torso per aumentare di 4 ciascuna delle cinque caratteristiche." },
    [16254] = { enName = "Formula: Enchant Weapon - Lifestealing", itName = "Formula: Incanta Arma - Rubavita", enDescription = "Teaches you how to permanently enchant a weapon to occasionally steal some of the health of the foe and give it to the wielder.", description = "Insegna a incantare permanentemente un’arma che occasionalmente sottrae salute al nemico e la trasferisce a chi la impugna." },
