    [19445] = { enName = "Formula: Enchant Weapon - Agility", itName = "Formula: Incanta Arma - Agilità", enDescription = "Teaches you how to permanently enchant a weapon to increase your agility by 15.", description = "Insegna a incantare permanentemente un’arma per aumentare di 15 l’Agilità." },
