    [19448] = { enName = "Formula: Enchant Weapon - Mighty Spirit", itName = "Formula: Incanta Arma - Spirito Vigoroso", enDescription = "Teaches you how to permanently enchant a weapon to increase your spirit by 22.", description = "Insegna a incantare permanentemente un’arma per aumentare di 22 lo Spirito." },
    [19449] = { enName = "Formula: Enchant Weapon - Mighty Intellect", itName = "Formula: Incanta Arma - Intelletto Vigoroso", enDescription = "Teaches you how to permanently enchant a weapon to increase your intellect by 22.", description = "Insegna a incantare permanentemente un’arma per aumentare di 22 l’Intelletto." },
