    [20730] = { enName = "Formula: Enchant Gloves - Healing Power", itName = "Formula: Incanta Guanti - Potere di Guarigione", enDescription = "Teaches you how to permanently enchant gloves to increase the healing done by spells and abilities by up to 35 and damage spells by up to 12.", description = "Insegna a incantare permanentemente i guanti per aumentare fino a 35 le cure e fino a 12 i danni inflitti da incantesimi e abilità." },
    [20731] = { enName = "Formula: Enchant Gloves - Superior Agility", itName = "Formula: Incanta Guanti - Agilità Massima", enDescription = "Teaches you how to permanently enchant gloves to increase Agility by 15.", description = "Insegna a incantare permanentemente i guanti per aumentare di 15 l’Agilità." },
    [20734] = { enName = "Formula: Enchant Cloak - Stealth", itName = "Formula: Incanta Mantello - Furtività", enDescription = "Teaches you how to permanently enchant a cloak to increase your stealth as if you were 1 level higher.", description = "Insegna a incantare permanentemente un mantello per aumentare la furtività come se il personaggio fosse di 1 livello superiore." },
    [20735] = { enName = "Formula: Enchant Cloak - Subtlety", itName = "Formula: Incanta Mantello - Scaltrezza", enDescription = "Teaches you how to permanently enchant a cloak to reduce how threatening the wearer is to monsters by 2%.", description = "Insegna a incantare permanentemente un mantello per ridurre del 2% la minaccia generata da chi lo indossa contro i mostri." },
